#include "waterfall_view.h"
#include "ui_language.h"
#include <algorithm>
#include <cmath>
#include <vector>
#include <stdexcept>
bool WaterfallView::create(CWnd* parent){const auto cls=AfxRegisterWndClass(0,::LoadCursorW(nullptr,IDC_ARROW),GetSysColorBrush(COLOR_3DFACE));return CreateEx(0,cls,L"FFT waterfall",WS_CHILD,CRect(0,0,1,1),parent,6030)!=FALSE;}
void WaterfallView::append(const WaterfallFrame& frame,size_t depth,double low,double high){if(!std::isfinite(low)||!std::isfinite(high)||low>=high||low<-200||high>200)throw std::runtime_error("Waterfall dB limits must increase within -200..200.");low_=low;high_=high;depth_=depth;history_.push(frame,depth);Invalidate(FALSE);}
LRESULT WaterfallView::WindowProc(UINT message,WPARAM w,LPARAM l){if(message==WM_SETFONT){if(w)SetPropW(m_hWnd,L"SCC.Waterfall.Font",reinterpret_cast<HANDLE>(w));else RemovePropW(m_hWnd,L"SCC.Waterfall.Font");if(l)Invalidate(FALSE);return 0;}if(message==WM_GETFONT)return reinterpret_cast<LRESULT>(GetPropW(m_hWnd,L"SCC.Waterfall.Font"));if(message==WM_NCDESTROY)RemovePropW(m_hWnd,L"SCC.Waterfall.Font");if(message==WM_ERASEBKGND)return TRUE;if(message==WM_PAINT){CPaintDC target(this);CRect area;GetClientRect(&area);if(area.Width()<100||area.Height()<80)return 0;CDC memory;memory.CreateCompatibleDC(&target);CBitmap bitmap;bitmap.CreateCompatibleBitmap(&target,area.Width(),area.Height());const auto old=memory.SelectObject(&bitmap);memory.FillSolidRect(area,RGB(245,245,245));memory.SetBkMode(TRANSPARENT);memory.SetTextColor(RGB(30,30,30));const auto currentFont=reinterpret_cast<HFONT>(SendMessage(WM_GETFONT));const auto font=memory.SelectObject(CFont::FromHandle(currentFont?currentFont:reinterpret_cast<HFONT>(GetStockObject(DEFAULT_GUI_FONT))));
        TEXTMETRICW metric{};memory.GetTextMetricsW(&metric);const int line=std::max(28L,metric.tmHeight+10);const auto& rows=history_.rows();CRect plot(65,line,area.right-20,area.bottom-line-8);memory.Rectangle(plot);
        if(!rows.empty()){const int width=static_cast<int>(rows.front().size()),height=static_cast<int>(rows.size());std::vector<uint32_t> pixels(static_cast<size_t>(width)*height);for(int y=0;y<height;++y)for(int x=0;x<width;++x){const auto level=static_cast<unsigned>(std::clamp((rows[y][x]-low_)/(high_-low_),0.0,1.0)*255);pixels[static_cast<size_t>(y)*width+x]=level|(level<<8)|(level<<16);}
            BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=width;info.bmiHeader.biHeight=-height;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;const int painted=std::max(1,static_cast<int>((plot.Height()-2)*rows.size()/depth_));StretchDIBits(memory.m_hDC,plot.left+1,plot.bottom-1-painted,plot.Width()-2,painted,0,0,width,height,pixels.data(),&info,DIB_RGB_COLORS,SRCCOPY);
            wchar_t label[160]{};swprintf_s(label,L"0 .. %.6g Hz | %.4g .. %.4g dB | %zu rows",history_.rate()/2,low_,high_,rows.size());memory.TextOutW(8,5,label);memory.TextOutW(4,plot.top+4,ui::caption(L"Older"));memory.TextOutW(4,plot.bottom-metric.tmHeight-3,ui::caption(L"Latest"));swprintf_s(label,L"%.6g s",history_.newest());memory.TextOutW(plot.left,plot.bottom+10,label);
        }else memory.TextOutW(plot.left+8,plot.top+8,ui::caption(L"Select a field and start waterfall."));memory.SelectObject(font);target.BitBlt(0,0,area.Width(),area.Height(),&memory,0,0,SRCCOPY);memory.SelectObject(old);return 0;}
    return CWnd::WindowProc(message,w,l);
}
